// CSD_RATIONALE_BEGIN
// GSM-symbolic strategy. Math word problems with intermediate symbolic
// expressions wrapped in << >> delimiters. Outside the span we use
// UnconstrainedChunk for amortized free reasoning text, breaking on "<<".
// Inside the span we use a group-boosted constrained step that softly prefers
// caller-supplied numeric/operator groups while the parser remains the hard
// authority. We close as soon as the parser reports a complete prefix.
// State tracked: steps (budget consumed) and the span open/closed flag plus
// the constrained suffix, which together let us prove parser-validity and
// progress invariants.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   - Unconstrained chunk branch: only flips insideConstrainedOut to true when
//     stoppedOnOpenSpan is reported, in which case currentConstrainedOut := []
//     is parser-valid by parser.IsValidPrefix([]).
//   - Complete-prefix close branch: CloseConstrainedSpan postcondition sets
//     insideConstrainedOut := false, making the implication vacuous.
//   - Constrained-step branch: GroupBoostedConstrainedStep returns EOS or a
//     parser-valid next token. EOS breaks. Otherwise AppendConstrainedToken
//     preserves parser.IsValidPrefix(currentConstrainedOut).
// progress:
//   - Unconstrained chunk: |generatedOut| <= |generated| + stepsUsed, and
//     steps grows by stepsUsed. Bound preserved.
//   - CloseConstrainedSpan: +1 step, appends at most one ">>" visible token.
//   - GroupBoostedConstrainedStep + AppendConstrainedToken: +1 step, appends
//     at most one visible token (EOS appends nothing but still counts as 1).
//   All branches keep |generated| <= |generatedPrefix| + steps.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Solve step by step. Wrap every intermediate arithmetic expression and the final numeric answer inside << >> delimiters, for example <<2+3=5>>.");

var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var remaining: nat := maxSteps - steps;
    var chunkBudget: nat := if remaining < 16 then remaining else 16;
    var chunkedG, stoppedOpen, stoppedEos, stepsUsed := helpers.UnconstrainedChunk(
      lm, prompt, generated, chunkBudget, "<<", eosToken
    );
    generated := chunkedG;
    steps := steps + stepsUsed;
    if stoppedEos {
      break;
    } else if stoppedOpen {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    } else if stepsUsed == 0 {
      // No forward progress possible in this chunk; bail to avoid stalling.
      break;
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.GroupBoostedConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

